enum { BC_RAR, BC_RAW_ATT, BC_RAW_COPY, BC_RAW_UAV, BC_ALL, BC_WAR = 6, BC_WAR_ATT = 7, BC_NONE = 255 };
#define BC_FOLD(c) ((c) == BC_WAR || (c) == BC_WAR_ATT ? BC_ALL : (c))
struct cmd { int kind; union { struct { void *res[8]; unsigned n; unsigned all; uint8_t cls[8]; uint8_t cls_noref; uint8_t rank; } barrier; char big[200]; } u; };
struct list { char pad0[40]; int closed; char pad1[12]; unsigned ncmds; unsigned ccap; char pad2[8]; struct cmd *cmds; };
typedef struct { int Type, Flags; void *res; unsigned sub, bs, as; int pad; } BAR;
static int32_t g_barriers, g_bc_war, r_barriers, r_bc_war; static int nat;
__attribute__((ms_abi)) static void natfn(void *l, unsigned n, const BAR *b){ nat++; }
/* reference: list_ResourceBarrier for one transition, flags 0 */
static void ref(struct list *l, const BAR *b){
  struct cmd *c; r_barriers++;
  if (l->ncmds && l->cmds[l->ncmds-1].kind == 9) c=&l->cmds[l->ncmds-1]; else { if (l->ncmds>=l->ccap) return; c=&l->cmds[l->ncmds++]; memset(c,0,sizeof *c); c->kind=9; }
  if (c->u.barrier.n==0 && !c->u.barrier.all) c->u.barrier.cls_noref=BC_NONE;
  const unsigned W=0x4|0x8|0x10|0x100|0x400|0x1000; unsigned bs=b->bs, as=b->as; uint8_t cls=BC_ALL;
  if (!as||!bs) cls=BC_ALL; else if (as&W) cls=(bs&W)?BC_ALL:!(as&~0x14u)?BC_WAR_ATT:BC_WAR; else if(!(bs&W)) cls=BC_RAR; else if(!(bs&~0x14u)) cls=BC_RAW_ATT; else if(bs==0x400) cls=BC_RAW_COPY; else if(bs==8) cls=BC_RAW_UAV;
  uint8_t rk = cls==BC_ALL?3:(cls==BC_WAR||cls==BC_WAR_ATT)?1:cls==BC_RAR?0:2; if (rk>c->u.barrier.rank) c->u.barrier.rank=rk;
  if (cls==BC_WAR||cls==BC_WAR_ATT) r_bc_war++;
  if (c->u.barrier.n<8){ c->u.barrier.cls[c->u.barrier.n]=cls; c->u.barrier.res[c->u.barrier.n++]=b->res; } else { c->u.barrier.all=1; c->u.barrier.cls_noref=BC_ALL; }
}
static void patch(unsigned char *p, size_t n, uint32_t m, uint32_t v){ for(size_t i=0;i+4<=n;i++) if(!memcmp(p+i,&m,4)){memcpy(p+i,&v,4);i+=3;} }
static void patch8(unsigned char *p, size_t n, unsigned char m, void *v){ unsigned char mm[8]; memset(mm,m,8); for(size_t i=0;i+8<=n;i++) if(!memcmp(p+i,mm,8)){memcpy(p+i,&v,8);i+=7;} }
